INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123539, 'spa', 'ser vencido por el desmayo (Nifal)', 'Nifal pasivo: ser vencido por el desmayo, ser presa del agotamiento. Lamentaciones 2:11 lo usa para los lactantes vencidos por el desfallecimiento (''cuando el niño se desmaya en las calles''). El marco pasivo presenta al sujeto como receptor del agotamiento en lugar de experimentarlo reflexivamente, enfatizando la indefensión.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123545, 'spa', 'Coronar, ceñir de honra', 'Coronar, otorgar una corona o guirnalda: ya sea literalmente, como cuando la madre de Salomón lo coronó (Cnt 3:11), o figuradamente de Dios que adorna con gloria y honra (Sal 8:5), misericordia y compasión (Sal 103:4), o la abundancia de un buen año (Sal 65:11). Isaías 23:8 extiende la metáfora a Tiro como la que distribuía coronas a las naciones.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123546, 'spa', 'Sustantivo femenino que designa una corona o guirnalda, en sentido literal y fig', 'Sustantivo femenino que designa una corona o guirnalda, en sentido literal y figurado. Literal: la corona amonita capturada por David (2 S 12:30), la corona de oro de Mardoqueo (Est 8:15), las coronas proféticas de Zacarías (Zac 6:11). Figurado: una esposa virtuosa corona a su marido (Pr 12:4), las canas coronan al anciano (Pr 16:31). Las traducciones convergen en ''corona'' (spa), ''couronne'' (fra), ''Krone'' (deu).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123554, 'spa', 'Nombre propio femenino', '1 Crónicas 2:26 registra: «Jerameel tuvo otra esposa llamada Atará, que fue madre de Onam.» El nombre aparece únicamente aquí. Como segunda esposa de Jerameel, engendró un hijo cuyos descendientes formaron un clan judita. Su inclusión en la genealogía asegura la legitimidad de su hijo dentro de la estructura tribal. El nombre «corona» puede reflejar su belleza o el honor que aportó a la familia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123555, 'spa', 'Topónimo múltiple', 'Topónimo que designa varias ciudades: (1) Atarot transjordana en el territorio de Gad (Números 32:3, 34), la moderna Aṭṭarûs, mencionada también en la Estela de Mesa; (2) Atarot-sofán (Números 32:35), de ubicación desconocida; (3) Atarot en la frontera Efraín-Benjamín (Josué 16:2, 7; posiblemente = Atarot-adar, 16:5; 18:13); y (4) Atarot-bet-joab en Judá (1 Crónicas 2:54).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123558, 'spa', 'Topónimo transjordano', 'Números 32:35 enumera Atrot-sofán entre las ciudades edificadas por los gaditas: «Atrot-sofán, Jazer, Jogbeha...» Las traducciones conservan el nombre compuesto (español «Atrot-Sofán»), distinguiéndolo de otras localidades llamadas Atarot. Los gaditas fortificaron ciudades en Galaad al establecerse en su heredad transjordana, siendo Atrot-sofán uno de esos asentamientos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123559, 'spa', 'Escombros de destrucción', 'Montones físicos de escombros tras una destrucción violenta. Se usa exclusivamente en contextos proféticos (Miqueas, Jeremías, Salmos) para describir el destino de Jerusalén y Samaria. Las traducciones multilingües lo vierten consistentemente como ''ruinas'' o ''montones'', reflejando las consecuencias de la conquista militar o el juicio divino. Destaca en Sal 79:1, donde se lamenta la desolación del templo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123560, 'spa', 'Hai (ciudad cananea)', 'Hai (ciudad cananea): la ciudad cananea cercana a Betel, central en la narrativa de la conquista. Siempre con el articulo ha-Ai (''la ruina''), aparece en Genesis como referencia geografica (Gn 12:8; 13:3, donde Abraham planto su tienda entre Betel y Hai) y domina Josue 7-8 con el primer ataque fallido, el pecado de Acan y la emboscada victoriosa. Tambien figura en el censo de los que regresaron (Esd 2:28; Neh 7:32).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123566, 'spa', 'Aja (asentamiento en Nehemias)', 'Aja (asentamiento en Nehemias): la variante ortografica Aja (עַיָּה), que aparece una vez en Neh 11:31 entre los asentamientos benjaminitas de la repoblacion postexilica. Sin articulo y con un patron vocalico diferente, esta forma puede representar una pronunciacion posterior o un asentamiento cercano pero distinto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123569, 'spa', 'Pueblo árabe joctanita', '1 Crónicas 1:22 enumera a Ebal entre los hijos de Joctán en la recapitulación genealógica de la Tabla de las Naciones. El paralelo en Génesis 10:28 presenta «Obal», evidenciando variación textual. Estos descendientes de Joctán representan pueblos árabes establecidos en el sur de Arabia. La ubicación exacta de Ebal/Obal es incierta, pero pertenece al grupo de tribus semíticas meridionales.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123571, 'spa', 'Monte Ebal (topónimo)', 'El monte de la maldición al norte de Siquem, designado en la ceremonia del pacto mosaico como sitio para proclamar las maldiciones (Dt 27:4, 13), frente al monte Gerizim. En Josué 8:30, 33 se describe la ceremonia de renovación del pacto tras la caída de Hai, con la mitad de las tribus sobre cada monte. El nombre se transliteró uniformemente como ''Ebal'' en español, francés y alemán.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123572, 'spa', 'Ciudad de Neftalí', 'Tres apariciones, todas en relatos históricos de invasiones extranjeras. La ciudad figura en los libros de Reyes y Crónicas como víctima de maniobras geopolíticas: primero la agresión siria, luego la asiria. Los relatos paralelos en Reyes y Crónicas muestran consistencia textual en la preservación de este topónimo, con variaciones menores de transliteración.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123573, 'spa', 'Abalanzarse con voracidad', 'En 1 Samuel 14:32, el ejército, agotado por el hambre tras el juramento de Saúl, ''se abalanzó sobre el botín'', degollando animales y comiendo carne con sangre. El verbo transmite la urgencia desesperada y la violencia del acto. El contexto es la insensata prohibición de Saúl que llevó a su pueblo a transgredir la ley mosaica sobre el consumo de sangre.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123574, 'spa', 'Increpar con violencia', 'En 1 Samuel 25:14, un siervo informa a Abigail que David envió mensajeros y Nabal ''los increpó a gritos''. El contexto revela un abuso verbal desmedido ante una petición razonable. Los siervos reconocieron que la respuesta insultante de Nabal provocaría represalias, lo que llevó a la sabia intervención de Abigail para evitar la destrucción de su casa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123575, 'spa', 'Apropiación codiciosa', 'En 1 Samuel 15:19, Samuel acusa a Saúl: ''¿Por qué no obedeciste la voz de YHWH? ¿Por qué te abalanzaste sobre el botín e hiciste lo malo ante Sus ojos?'' El verbo transmite la codicia rapaz de apoderarse del botín prohibido. El contexto es la obediencia parcial de Saúl, que conservó los mejores animales y al rey amalecita con vida en lugar de cumplir el mandato de destrucción total.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123576, 'spa', 'Ave de rapiña', 'Ave de presa o rapaz, usada tanto colectivamente para aves carroñeras como individualmente para un solo depredador alado. En Génesis 15:11, las aves de rapiña descienden sobre el sacrificio del pacto de Abram, una intrusión ominosa que él debe ahuyentar. Isaías 46:11 aplica célebremente el término a Ciro como instrumento de Dios: ''un ave de rapiña del oriente, el hombre de mi consejo''. Ezequiel 39:4 e Isaías 18:6 describen rapaces alimentándose tras juicios divinos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123582, 'spa', 'Etam (topónimo y clan)', 'Nombre geográfico y de clan que designa la peña donde se ocultó Sansón (Jue 15:8, 11), una ciudad fortificada cerca de Belén reconstruida por Roboam (2 Cr 11:6), un clan judío (1 Cr 4:3) y posiblemente una localidad simeonita (1 Cr 4:32). Las traducciones transliteran uniformemente como ''Etam''. El nombre podría derivar de עַיִט (''ave de rapiña''), aunque la etimología permanece discutida.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123585, 'spa', 'Perpetuidad o eternidad', 'En 2 Crónicas 33:7, Manasés coloca un ídolo ''en la casa de Dios, de la cual Dios había dicho a David y Salomón: pondré Mi Nombre para siempre''. La forma textual es inusual, posiblemente una variante del término común para ''eternidad''. El contexto subraya la trágica ironía: Dios prometió que Su nombre habitaría allí perpetuamente, pero Manasés profanó ese mismo lugar con un ídolo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123586, 'spa', 'Guerrero de David', 'En 1 Crónicas 11:29 se lista a ''Ilai el ahohíta'' entre los Treinta, la guardia de élite de David. El pasaje paralelo en 2 Samuel lo llama Zalmón, generando incertidumbre sobre si son dos nombres para la misma persona o un problema textual. Como ahohíta, Ilai pertenecía a una familia benjaminita distinguida por producir guerreros. Su inclusión entre los héroes de David inmortaliza su nombre entre los más grandes combatientes de Israel.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123587, 'spa', 'Reino antiguo oriental', 'Jeremías 49:36 declara el juicio divino: ''Traeré sobre Elam los cuatro vientos de los cuatro extremos del cielo, y los dispersaré a todos esos vientos.'' El contexto es el oráculo de Dios contra diversas naciones; el juicio sobre Elam implica la dispersión total y la destrucción de su poder como nación de arqueros. No obstante, el versículo 39 promete restauración futura.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123588, 'spa', 'Elam (nacin/regin) -- nombre propio de la antigua nacin y regin al este de Mesop', 'Elam (nacin/regin) -- nombre propio de la antigua nacin y regin al este de Mesopotamia, que abarcaba el rea alrededor de Susa en el actual suroeste de Irn. Listado entre los hijos de Sem en Gnesis 10:22 y 1 Crnicas 1:17, aparece en narrativas histricas como potencia militar (Gn 14:1, 9), en orculos profticos de juicio (Jer 49:34-39; Ez 32:24) y como tierra de dispersin israelita (Is 11:11). Daniel 8:2 identifica a Susa como su capital.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123593, 'spa', 'Elam (persona/clan)', 'Nombre propio de persona y clan para familias israelitas del período postexílico, distinto de la nación mesopotámica Elam. Dos grupos de ''hijos de Elam'' aparecen en las listas de retornados (Esd 2:7, 31; Neh 7:12, 34), y miembros de la familia figuran entre quienes repudiaron a esposas extranjeras (Esd 10:2, 26). Un benjaminita llamado Elam aparece en 1 Crónicas 8:24, un portero levítico en 1 Crónicas 26:3, y un firmante del pacto en Nehemías 10:14.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123595, 'spa', 'Ardor del aliento divino', 'Isaías 11:15 describe a Dios secando el Éufrates: ''Agitará su mano sobre el río con el ardor de su aliento.'' El texto es difícil y algunos proponen enmiendas. El contexto más amplio es un nuevo éxodo en el que Dios elimina obstáculos, dividiendo el río para que su pueblo cruce, evocando la travesía del mar Rojo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123596, 'spa', 'Ojo en constructo', 'Tres frases constructas que muestran «ojo» en expresiones de atención divina (2 Sam 16:12), encuentro cara a cara (Jer 32:4) y severidad ordenada (Ez 9:5). La evidencia multilingüe revela la complejidad traductora: algunas versiones preservan la imagen literal del ojo, mientras otras vierten la fuerza idiomática. Las cadenas constructas del hebreo condensan expresiones que requieren formulaciones más extensas en otras lenguas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123598, 'spa', 'A los ojos de (evaluativo)', 'Modismo evaluativo-metafórico ''a los ojos de X'' o ''ante los ojos de X'', que significa ''según el juicio, la opinión o la estimación de X''. Este sentido dominante (734 apariciones) abarca la fórmula ''hallar gracia a los ojos de'' (Gn 6:8; 19:19), el estribillo deuteronomista ''hizo lo malo a los ojos del SEÑOR'' y toda construcción donde ''ojos'' representan perspectiva o aprobación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123617, 'spa', 'Ojo (órgano físico)', 'El órgano literal de la vista: ojos que ven, lloran, se oscurecen con la edad, se alzan en oración o sirven como referentes anatómicos. Con 127 apariciones, incluye los ''ojos delicados'' de Lea (Gn 29:17), los ojos de Israel ''pesados por la edad'' (Gn 48:10) y la fórmula del talión ''ojo por ojo'' (Éx 21:24).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123620, 'spa', 'Apariencia, aspecto visible', 'Apariencia exterior o superficie visible: extensión metafórica donde ''ojo'' significa ''lo que el ojo percibe'', usada para describir el aspecto visible de algo. Solo 11 apariciones, concentradas en descripciones del maná (''su aspecto era como aspecto de bedelio'', Nm 11:7) y las visiones de Ezequiel (''como aspecto de fuego'', Ez 1:4, 27; 8:2).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123697, 'spa', 'Una fuente natural de agua que brota de la tierra — manantial, fuente o venero', 'Una fuente natural de agua que brota de la tierra — manantial, fuente o venero. Este sentido dominante abarca las 21 ocurrencias, apareciendo en las narraciones de Agar junto al manantial (Gn 16:7), el encuentro de Rebeca en la fuente de la ciudad (Gn 24:13-45), los doce manantiales de Elim (Éx 15:27) y las fuentes cosmológicas del abismo (Pr 8:28). El español ''fuente'' y el francés ''source'' lo reflejan de manera consistente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123708, 'spa', 'Una única ocurrencia incierta en Os 10', 'Una única ocurrencia incierta en Os 10:10 donde las glosas — inglés ''[their eyes]'', español ''[iniquidades]'' — divergen marcadamente del significado de manantial, lo que sugiere fuertemente una confusión de homógrafos con H5869a (ojo) o un artefacto de importación de datos, más que un sentido genuinamente distinto de este lexema.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123709, 'spa', 'Ojo (físico y figurado)', 'El ojo en sentido tanto físico como figurado: en Esdras 5:5 el ''ojo de su Dios'' denota la protección vigilante divina sobre los líderes judíos que reconstruían el templo. En Daniel 7:8 y 7:20, el cuerno con ojos humanos evoca una inteligencia inquietante y vigilante, mientras que en Daniel 4:34 el rey alza sus ojos al cielo en señal de cordura recobrada. El español traduce directamente como ''ojos/ojo''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123710, 'spa', 'Ayin (topónimo)', 'Nombre geográfico que designa localidades asociadas con manantiales. En la frontera cananea (Nm 34:11) la LXX lo traduce como ''fuentes'', revelando el sentido topográfico tras el nombre. En el Néguev aparece constantemente junto a Rimón en las asignaciones tribales de Judá y Simeón (Jos 15:32; 19:7; 1 Cr 4:32). Las traducciones multilingües transliteran uniformemente como Ain o Ayin.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123711, 'spa', 'En-gadi (topónimo)', 'El topónimo En-gadi, un oasis desértico identificado con la moderna ʿAin Yidi en la ribera occidental del mar Muerto. Aparece entre las ciudades del desierto de Judá (Jos 15:62) y sirvió como refugio de David frente a Saúl en sus cuevas y fortalezas (1 Sam 23:29; 24:1). El Cantar de los Cantares celebra sus viñedos (Cnt 1:14) y la visión escatológica de Ezequiel sitúa allí pescadores (Ez 47:10).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123718, 'spa', 'Topónimo israelita', 'Tres apariciones referidas a dos ciudades distintas. Josué 15:34 menciona el En-ganim de Judá, mientras que Josué 19:21 y 21:29 se refieren a la ciudad de Isacar. Las variadas traducciones de la Septuaginta reflejan la complejidad textual y la frecuencia de topónimos compuestos con «fuente» en la antigua Palestina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123719, 'spa', 'Topónimo bíblico', 'Tres apariciones: asignación territorial en Josué, consulta de Saúl a la médium en 1 Samuel y victoria militar recordada en Salmos. La ciudad aparece en contextos muy distintos —reparto de tierras, necromancia real desesperada y triunfo militar— lo que revela su larga historia. La Septuaginta ofrece grafías variadas (Aeldor, Aendo).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123720, 'spa', 'Manantial de provisión divina', 'Jueces 15:19 explica el nombre: ''Dios abrió la hendidura que hay en Lehi, y salió agua; él bebió, su espíritu se reanimó y revivió. Por eso llamó aquel lugar En-hacore, que está en Lehi hasta hoy.'' El manantial conmemoró la provisión de Dios cuando Sansón estaba al borde de la muerte por sed tras su victoria.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123721, 'spa', 'Ciudad de Isacar', 'Josué 19:21 enumera En-hada entre las ciudades de Isacar: ''y En-hada y Bet-pases.'' El contexto es la distribución territorial a Isacar, una de las tribus menores. El manantial que dio nombre a la ciudad era presumiblemente lo bastante significativo para sostener un asentamiento, aunque su identificación moderna sigue siendo incierta.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123722, 'spa', 'Ciudad de Neftalí', 'Asentamiento en el territorio de Neftalí mencionado en Josué 19:37. La evidencia multilingüe preserva consistentemente el nombre propio con el prefijo ''En-'', indicando un topónimo asociado con un manantial. Esta única mención lo sitúa dentro del contexto de los marcadores fronterizos territoriales en la distribución de la tierra prometida realizada por Josué.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123723, 'spa', 'Manantial de Harod', 'El manantial donde acampó el ejército de Gedeón en Jueces 7:1, marcando el inicio de una de las victorias militares más extraordinarias de Israel. Las traducciones en múltiples idiomas enfatizan consistentemente el elemento del manantial, reflejando la importancia narrativa del lugar donde Dios demostró que la victoria no dependía de la cantidad de soldados.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123724, 'spa', 'Topónimo judeano', 'Tres apariciones: dos en el relato de Tamar y una en la lista de fronteras de Josué. La evidencia multilingüe muestra transliteración con variación prepositiva. El relato de Génesis confiere a esta ciudad un lugar significativo en la historia de la salvación, aunque su ubicación exacta sigue siendo incierta. La forma dual del nombre («manantiales» en plural) se conserva en algunas traducciones.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123725, 'spa', 'Nombre antiguo de Cades', 'Nombre antiguo de Cades-Barnea mencionado en Génesis 14:7 durante el relato de la campaña de los reyes. Las traducciones principales conservan la forma del nombre propio «En-Mispat», reconociéndolo como el mismo lugar que más tarde adquiriría fama durante la experiencia de Israel en el desierto. El componente ''juicio'' del nombre podría anticipar las asociaciones posteriores de este sitio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123726, 'spa', 'Enán (nombre propio)', 'Nombre propio del padre de Ahira, jefe tribal de Neftalí durante las peregrinaciones por el desierto. Sus cinco apariciones se encuentran en Números en listados tribales formularios: censos, disposición del campamento y ofrendas de dedicación del tabernáculo. Las traducciones transliteran uniformemente como ''Enán'' en español y ''Enan'' en inglés, francés y alemán, conservando la forma hebrea.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123727, 'spa', 'Lugar profético restaurado', 'Localidad profética mencionada en Ezequiel 47:10 como parte de la región restaurada y fecunda del Mar Muerto. La Septuaginta la transcribe como ''Enagaleim'', mientras que las traducciones modernas conservan la forma del nombre propio. Su emparejamiento con En-Gadi en la visión establece dos puntos limítrofes para la actividad pesquera que caracterizará la tierra sanada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123728, 'spa', 'Manantial fronterizo', 'Manantial con nombre propio que servía como hito geográfico en la frontera entre Judá y Benjamín. El nombre compuesto עֵין (''fuente'') más רֹגֵל (''batanero/espía'') aparece en las delimitaciones tribales (Jos 15:7; 18:16) y en las narrativas de la corte davídica como escenario de intrigas políticas (2 S 17:17; 1 R 1:9).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123729, 'spa', 'Pueblo postexílico de Judá', 'Pueblo en la Judá postexílica enumerado en Nehemías 11:29 entre los asentamientos reocupados por los que regresaron de Babilonia. La naturaleza compuesta del nombre, que combina ''manantial'' y ''granada'', sugiere una ubicación fértil que atrajo a los colonos. Su mención en las listas de repoblación confirma la continuidad de la vida comunitaria tras el exilio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123731, 'spa', 'Frontera Efraín-Manasés', 'Localidad fronteriza entre Efraín y Manasés mencionada en Josué 17:7. Las traducciones principales conservan la forma del nombre propio, reconociendo su función como marcador geográfico fijo. El prefijo עֵין (''manantial'') resulta clave para comprender por qué este punto específico servía como límite reconocido en la distribución territorial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123732, 'spa', 'Desfallecimiento físico', 'Estado de debilidad física extrema o desmayo, empleado específicamente en Jeremías 4:31 donde el alma de la hija de Sion desfallece en angustia. El español «desfallece» capta bien este sentido. El contexto enfatiza un agotamiento que amenaza la vida, comparando la experiencia con una mujer que da a luz por primera vez, imagen poderosa de vulnerabilidad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123733, 'spa', 'Cansado, agotado por el esfuerzo -- fsicamente fatigado o exhausto por el esfuer', 'Cansado, agotado por el esfuerzo -- fsicamente fatigado o exhausto por el esfuerzo, el trabajo, el viaje o la batalla. El agotamiento faminto de Esa tras la caza (Gn 25:29-30), los soldados de Geden que avanzan ''desfallecidos pero persiguiendo'' (Jue 8:4-5) y la compaa exhausta de David junto al Jordn (2 Sam 16:14; 17:29) ilustran este sentido bsico. Deuteronomio 25:18 lo empareja con יָגֵעַ (''fatigado'') para describir a los rezagados vulnerables de Israel.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123740, 'spa', 'Desfallecido, sediento -- desfallecido o reseco especficamente por la sed y la p', 'Desfallecido, sediento -- desfallecido o reseco especficamente por la sed y la privacin, donde el agotamiento se solapa con la necesidad desesperada de agua. Job 22:7 reprocha negar agua al sediento (עָיֵף), y el Salmo 143:6 compara el alma del salmista con ''una tierra sedienta'' que anhela a Dios. Mientras la fatiga fsica del sentido 1 se remedia con descanso, este sentido implica un agotamiento ms profundo, que solo la bebida o el refrigerio divino pueden saciar.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123744, 'spa', 'Nombre propio múltiple', 'Nombre propio que llevan varias figuras bíblicas: un ancestro del clan madianita descendiente de Abraham y Cetura, un hombre en la genealogía de Judá y una concubina de Caleb. El gentilicio en Génesis 25:4 y 1 Crónicas 1:33 designa una subtribu árabe, mientras que Isaías 60:6 profetiza que los camellos de Efa llevarán oro e incienso a Jerusalén.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123746, 'spa', 'ciudad, pueblo', 'Asentamiento urbano habitado, ya sea una gran ciudad fortificada o un pueblo menor, abarcando todo el espectro desde la primera ciudad de Caín (Gn 4:17) hasta las ciudades fortificadas de Judá y los usos metafóricos y escatológicos. La evidencia interlingüística — español ciudad, francés ville, alemán Stadt — converge en un único significado indiviso de habitación urbana.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123824, 'spa', 'Nombre propio', 'Nombre personal en 1 Crónicas 7:12 dentro de la genealogía de Benjamín. Las traducciones multilingües muestran decisiones interesantes: el inglés y el español conservan «Ir» como nombre propio, mientras que el francés y el alemán lo traducen como «ville» y «Stadt» (ciudad), reflejando la coincidencia semántica con el sustantivo común. Esta única mención ilustra cómo nombres propios y palabras comunes podían compartir la misma forma.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123825, 'spa', 'Ser angélico vigilante', 'Tres apariciones en Daniel 4, todas describiendo a estos mensajeros angélicos. La evidencia multilingüe muestra variación interesante: algunas versiones conservan «vigilante/despierto», mientras que otras confunden el término con עִיר («ciudad»). El contexto arameo y el género apocalíptico de Daniel respaldan la interpretación angélica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123826, 'spa', 'Asno joven, pollino', 'Un asno joven, pollino o potro — vigoroso y útil para montar o llevar cargas. Génesis 32:15 lista diez pollinos entre el generoso regalo de Jacob a Esaú. La profecía mesiánica de Zacarías 9:9 empareja célebremente ''asno'' con ''pollino hijo de asna'', cumplida en la entrada de Jesús a Jerusalén. En Génesis 49:11, la figura real ''ata su pollino a la vid'', imagen de bendición sobreabundante.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123833, 'spa', 'Ciudad, pueblo (homógrafo)', 'Un homógrafo que significa ''ciudad'' o ''pueblo'', un lexema distinto que comparte solo la forma consonántica con la palabra para asno. En Jueces 10:4, los treinta hijos de Jaír montaban treinta pollinos y tenían treinta ciudades (ayarim) — un juego de palabras deliberado que aprovecha la homofonía entre ambos términos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123835, 'spa', 'Ira (nombre propio)', 'Nombre masculino propio que designa a tres hombres en la administración y élite militar de David. El portador más distintivo es Ira el jairita, llamado כֹּהֵן de David, término debatido entre ''sacerdote'' y ''consejero principal'' (2 Sam 20:26). Los otros dos son guerreros entre los célebres ''treinta'' de David: Ira el tecoíta (2 Sam 23:26 = 1 Cr 11:28) e Ira el itrita (2 Sam 23:38 = 1 Cr 11:40).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123837, 'spa', 'Topónimo del desierto', 'Ciudad en el desierto de Judá mencionada en Josué 15:62. Las traducciones preservan consistentemente el nombre propio con la conjunción (español: «y-Ir-Hamelaj»). La naturaleza descriptiva del nombre —«ciudad de la sal»— proporciona contexto ambiental para entender este asentamiento del desierto de Judá, aunque su ubicación precisa permanece desconocida.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123838, 'spa', 'Nombre personal', 'Nombre propio en la genealogía de Judá que se encuentra en 1 Crónicas 4:15. Las traducciones conservan uniformemente esta forma como nombre propio (español: «Irú»). La única atestación ofrece información mínima, pero sitúa a Irú dentro del linaje de Caleb, conectándolo con uno de los espías fieles más célebres y con la herencia de Judá en Hebrón.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123839, 'spa', 'Nombre benjaminita', 'Nombre personal benjaminita que se encuentra en 1 Crónicas 7:7. La evidencia multilingüe lo muestra con la conjunción (español: «y-Iri»), indicando su posición dentro de la lista de los hijos de Bela. Esta única mención sitúa a Iri dentro de la estructura genealógica de Benjamín, contribuyendo a nuestra comprensión de cómo la tribu más pequeña organizaba sus relaciones claniles.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123841, 'spa', 'Desnudo, sin ropa', 'Adjetivo que describe estar sin vestidura. En Génesis 3:7 Adán y Eva descubren que están desnudos (עֵירֻמִּם, plural); 3:10-11 repite la forma singular en el diálogo de vergüenza. Ezequiel lo emplea para la Jerusalén personificada como infante (16:7) y como mujer despojada en juicio (16:22, 39; 23:29).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123844, 'spa', 'Desnudez abstracta', 'La desnudez como sustantivo abstracto, designando la condición de estar expuesto y privado de todo. En Deuteronomio 28:48, la maldición del pacto advierte que Israel servirá a sus enemigos ''con hambre, con sed, con desnudez y con falta de todas las cosas''. Aquí la desnudez es un estado de privación, no una descripción física.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123845, 'spa', 'Topónimo en Judá', 'Nombre de lugar en 1 Crónicas 4:12, dentro de la genealogía de Judá. Las traducciones lo conservan como nombre propio (Ir-Najas), manteniendo la forma compuesta que asocia el asentamiento con נָחָשׁ, ya sea como referencia a una persona, a la metalurgia del bronce o a otro rasgo distintivo. Su única mención deja incierto el contexto histórico preciso.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123846, 'spa', 'Ciudad en Dan', 'Pueblo asignado a Dan en Josué 19:41, idéntico a Bet-Semes. Las traducciones mantienen el nombre propio de forma consistente. El elemento solar en el nombre refleja el trasfondo religioso cananeo de la región antes del asentamiento israelita, mientras que el nombre alternativo Bet-Semes se hizo más común en los textos bíblicos posteriores.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123848, 'spa', 'Acbor (nombre propio)', 'Nombre propio masculino Acbor/Ajbor, etimológicamente vinculado a la palabra hebrea para ''ratón'' (עַכְבָּר). Identifica a dos figuras: un patriarca edomita cuyo hijo Baal-Hanán llegó a ser rey (Gn 36:38-39; 1 Cr 1:49), y un cortesano judío bajo Josías involucrado en la consulta a la profetisa Hulda (2 R 22:12, 14). En español se traduce generalmente como ''Acbor'' o ''Ajbor''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123853, 'spa', 'Ratón / rata (roedor)', 'Un ratón o rata, el roedor común. Declarado ritualmente impuro en el Código de Santidad (Lev 11:29) junto con lagartijas y otras criaturas rastreras. El uso más extenso aparece en la narrativa de la plaga filistea, donde ratones de oro (עַכְבְּרֵי הַזָּהָב) fueron modelados como ofrendas votivas para detener la plaga que asolaba su tierra (1 Sam 6:4-5, 11, 18). Isaías 66:17 condena a quienes comen carne de ratón en rituales sincretistas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123856, 'spa', 'Puerto fenicio', 'Puerto fenicio mencionado en Jueces 1:31 como una de las ciudades que Aser no expulsó. Todas las traducciones principales lo transcriben uniformemente como ''Aco'' o ''Ako''. Su mención en Jueces 1 subraya la persistente presencia cananea en las regiones costeras de Israel, con importantes implicaciones para la interacción cultural y religiosa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123857, 'spa', 'Valle de turbación', 'Topónimo que significa ''turbación'' o ''perturbación,'' identificando un valle cerca de Jericó vinculado a la transgresión de Acán y sus consecuencias (Jos 7:24, 26). La denominación etiológica se conecta con el verbo עָכַר, ''causar turbación.'' Proféticamente, tanto Oseas 2:15 como Isaías 65:10 transforman este lugar de juicio en símbolo de restauración y esperanza futura.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123858, 'spa', 'Acán (nombre propio)', 'Nombre propio masculino que designa al judío que violó el anatema sobre las cosas consagradas de Jericó, provocando una catástrofe militar sobre Israel. La narrativa de Josué 7 detalla su confesión y ejecución en el Valle de Acor (Jos 7:1, 18-20, 24). La forma alternativa עָכָר (1 Cr 2:7) lo vincula explícitamente con la raíz עכר (''turbar''), reforzando el juego de palabras etiológico en Jos 7:25-26.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123859, 'spa', 'Tintinear con ajorcas', 'El acto de hacer sonar intencionalmente los adornos de tobillo, presente en Isaías 3:16 como parte de la denuncia profética contra las mujeres orgullosas de Judá. El español ''hacen tintinear'' capta la cualidad onomatopéyica de esta producción deliberada de sonido. La crítica de Isaías va más allá de la moda para denunciar la complacencia espiritual de una sociedad entregada al lujo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123861, 'spa', 'Hija de Caleb', 'Nombre personal femenino que designa a la hija de Caleb, dada en matrimonio a Otoniel por su valor militar. Su importancia narrativa radica en la iniciativa de pedir manantiales de agua, asegurando recursos vitales para su hogar en el árido Néguev (Jos 15:16-17; Jue 1:12-13; 1 Cr 2:49).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123862, 'spa', 'turbar, acarrear calamidad', 'Qal activo: turbar, perturbar o acarrear calamidad sobre alguien. En Génesis 34:30 Jacob lamenta que Simeón y Leví lo han ''turbado'' al provocar a los cananeos. Josué 7:25 ofrece el uso definitivo: ''¿Por qué nos has turbado? El SEÑOR te turbará hoy'', un juego de palabras con el nombre de Acán y el Valle de Acor. Proverbios advierte que el codicioso turba su propia casa (11:29; 15:27).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123870, 'spa', 'ser turbado, agitarse', 'Nifal estativo/pasivo: ser turbado, agitarse o encontrarse en estado de perturbación. El Salmo 39:2 emplea el Nifal perfecto — ''mi dolor se agitó'' — para describir la conmoción interior cuando el salmista intentaba guardar silencio. Proverbios 15:6 habla de un hogar que ''es turbado'' por las ganancias mal habidas. El cambio al pasivo enfatiza la experiencia de quien padece la perturbación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123875, 'spa', 'Perturbador de Israel', 'Nombre usado en 1 Crónicas 2:7 para el hombre que violó el anatema en Jericó, llamado Acán en Josué 7. Ambas formas están etimológicamente conectadas con ''perturbación'' o ''desastre''. Crónicas lo identifica explícitamente como ''el perturbador de Israel que quebrantó la fe en el asunto del anatema'', asegurando que las generaciones posteriores recordaran la lección.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123876, 'spa', 'Padre de Pagiel', 'Nombre personal masculino que identifica al padre de Pagiel, el líder tribal de Aser en la generación del desierto. Las cinco ocurrencias aparecen en Números dentro de fórmulas estandarizadas de enumeración tribal: censo, orden de campamento y ofrendas de dedicación (Nm 1:13; 2:27; 7:72, 77; 10:26).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123877, 'spa', 'Criatura venenosa', 'Criatura venenosa en el Salmo 140:3, muy probablemente una víbora o áspid según las traducciones antiguas. Las glosas multilingües tratan consistentemente este término como una serpiente peligrosa. El contexto poético enfatiza el veneno mortal «debajo de sus labios», convirtiéndolo en una poderosa metáfora de enemigos cuyas palabras destruyen como ponzoña.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123878, 'spa', 'Elevación con matiz divino', 'Altura como elevación espacial con resonancias teológicas. Las cuatro apariciones abarcan desde la exaltación real de David (2 Sam 23:1) hasta las acusaciones proféticas contra Israel por no volverse hacia Dios (Oseas 7:16; 11:7). En Sal 50:4 se usa para Dios que llama desde ''los cielos de arriba''. El patrón constante muestra ''hacia arriba / en lo alto'' con referencia implícita a la presencia divina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123879, 'spa', 'Sobre, encima de', 'Espacial y direccional: ''sobre, encima de, hacia'', indicando posición superior o movimiento hacia una persona o lugar. Es el sentido predominante en los pasajes arameos de Daniel, donde el dominio se establece ''sobre'' los reinos (Dn 4:17, 32) y el fuego no tiene poder ''sobre'' los cuerpos de los fieles (Dn 3:12).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123880, 'spa', 'Acerca de, tocante a', 'Temático: ''acerca de, tocante a'', donde la preposición marca el asunto del discurso o el informe, no la ubicación física. Cuando la reina comunica a Belsasar lo que ha oído ''acerca de'' Daniel (Dn 5:14, 16), עַל pasa de lo espacial a lo discursivo, distinguiéndose claramente del sentido ''sobre'' físico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123882, 'spa', 'Contra (adversativo)', 'Adversativo: ''contra'', expresando oposición o intención hostil. En Jeremías 49:30, Nabucodonosor ha trazado un plan ''contra ustedes'' (los habitantes de Hazor). Este uso adversativo aparece en contextos de amenaza militar o juicio divino, diferenciándose netamente de los sentidos espacial y temático.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123883, 'spa', 'sobre, en, encima de (espacial)', 'Sentido espacial central (grupo duplicado o dividido). Expresa la misma relación de superficie que el sentido 1, posiblemente una distinción contextual sutil.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123903, 'spa', 'contra (adversativo)', 'Oposición o enemistad: «contra». Génesis 50:20 «vosotros pensasteis mal contra mí». Expresa hostilidad, confrontación u oposición directa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123923, 'spa', 'a causa de, por lo tanto (causal)', 'Razón o fundamento. 51 ocurrencias. Génesis 20:6 «por eso te detuve de pecar». Introduce la causa, motivo o razón de una acción o situación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123924, 'spa', 'junto a, al lado de (proximidad)', 'Cercanía sin contacto de superficie. 55 ocurrencias. Gén 24:13 «de pie junto al manantial». Indica proximidad espacial o presencia cercana sin implicar contacto físico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123941, 'spa', 'acerca de, concerniente a (tópico)', 'Asunto o tema del habla o pensamiento. 39 ocurrencias. Gén 21:25 «acerca del pozo». Introduce el tema o materia sobre la cual se habla o piensa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123945, 'spa', 'por, en favor de (benefactivo)', 'Beneficio derivado de una acción. 22 ocurrencias. Lev 16:30 «hacer expiación por vosotros». Indica que la acción beneficia o favorece a alguien.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123947, 'spa', 'según, además de (normativo)', 'Sentido de norma o estándar y aditivo. 13 ocurrencias. Éxo 6:26 «según sus ejércitos». Indica conformidad con un patrón o adición a algo existente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123960, 'spa', '(contexto incierto)', 'Siete ocurrencias de contexto incierto o dependiente. Uso especializado que requiere análisis contextual específico para determinar el sentido preciso.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123963, 'spa', 'hacia, a (direccional)', 'Movimiento hacia una meta. 19 ocurrencias. Éxo 3:18 «vayamos... al SEÑOR». Expresa dirección o destino del movimiento.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (124005, 'spa', 'Porque (causal)', 'Uso causal dominante, ''porque'', donde la frase fundamenta enfáticamente una acción en una razón declarada. En Gn 18:5, Abraham ofrece pan porque sus huéspedes pasaron por su camino; en Nm 14:43, Moisés advierte que los amalecitas están listos porque Israel se apartó del SEÑOR. La acumulación de כִּי + עַל + כֵּן confiere mayor peso retórico que un simple כִּי.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (124007, 'spa', 'Por tanto (consecutivo)', 'Un matiz consecutivo más raro, ''por tanto'', donde la frase extrae una conclusión del contexto previo en vez de citar una causa. Jacob dice a Esaú en Gn 33:10 que ver su rostro es como ver el de Dios — por tanto le ruega que acepte el regalo. El paso de causa retrospectiva a consecuencia prospectiva es sutil pero real.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (124013, 'spa', 'sobre, encima de', 'El sentido espacial primario, superesivo: ''sobre, encima de, por encima de'', que representa 75 de 103 ocurrencias. Cubre posición física sobre una superficie, autoridad ejercida sobre un dominio y superposición general, apareciendo de manera constante en las secciones arameas de Esdras y Daniel (Esd 4:11-20; Dn 2:28-46).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (124017, 'spa', 'acerca de, respecto a', 'Sentido temático o referencial: ''acerca de, respecto a, concerniente a''. La preposición marca el asunto en discusión. Los compañeros de Daniel declaran que no necesitan responder al rey ''acerca de'' este asunto (Dn 3:16); Daniel es alabado por la sabiduría hallada en él ''respecto a'' la interpretación (Dn 5:14). Ocho ocurrencias con esta función discursiva.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (124018, 'spa', 'a, hacia', 'Extensión direccional o dativa: ''a, hacia'', indicando movimiento hacia un destino o el receptor indirecto de una acción. Trece ocurrencias portan este sentido, como en cartas enviadas ''al'' rey (Esd 4:11-12; 5:7). La extensión semántica va de la posición estática a la meta del movimiento.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (124019, 'spa', 'contra', 'Sentido adversativo: ''contra'', expresando oposición u hostilidad. Rehúm y Simsai escriben ''contra'' Jerusalén (Esd 4:8); la expresión de Nabucodonosor se demuda ''contra'' Sadrac, Mesac y Abednego (Dn 3:19). Cuatro ocurrencias, traducidas consistentemente con contra, distinguiéndose del sentido espacial neutro.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (124024, 'spa', 'a causa de, por qué', 'Sentido causal: ''a causa de, por razón de'', indicando motivo o fundamento para una acción. Daniel pregunta a Arioc ''por qué'' (literalmente ''¿a causa de qué?'') el decreto es tan severo (Dn 2:15), y la visión fue concedida no ''a causa de'' la sabiduría de Daniel sino por el bien del rey (Dn 2:30). Solo dos ocurrencias claras, ambas en Daniel 2.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (124029, 'spa', 'más que', 'Sentido comparativo-superlativo: ''más que, por encima de''. Una sola ocurrencia en Daniel 3:19, donde Nabucodonosor ordena calentar el horno siete veces ''más de'' lo acostumbrado. Solo el contexto desambigua esta rara extensión del significado básico de superposición.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (124035, 'spa', 'Yugo (carga/servidumbre)', 'Yugo (carga/servidumbre): barra de madera colocada sobre el cuello de los animales de tiro, usada literalmente en unos pocos contextos agricolas y rituales (Nm 19:2; Dt 21:3; 1 Sam 6:7), pero predominantemente como figura de subyugacion, servidumbre y opresion politica. La metafora es politicamente decisiva en el intercambio de Roboam que divide el reino (1 R 12:4-14). El acto profetico del yugo de Jeremias (Jer 27-28) dramatiza la sumision a Babilonia, mientras que la imagen liberadora recorre desde el Exodo hasta las promesas escatologicas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (124050, 'spa', 'Sobre, encima de', 'Adverbio arameo que significa «encima» o «sobre» en Daniel 6:2, describiendo funcionarios posicionados con autoridad sobre otros. Las glosas multilingües muestran el sentido espacial-jerárquico («y-sobre-ellos»), indicando la estructura administrativa del gobierno de Darío donde los comisarios supervisaban a los sátrapas. Esta única atestación aramea combina posición espacial con rango administrativo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (124051, 'spa', 'Nombre propio', 'Nombre personal en la genealogía de Aser que se encuentra en 1 Crónicas 7:39. Las traducciones preservan consistentemente este término como nombre propio, aunque su única mención no ofrece contexto narrativo. Su inclusión en el registro genealógico de Aser lo vincula a una de las tribus del norte cuyo territorio fue eventualmente perdido ante la conquista asiria.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (124052, 'spa', 'Habla tartamuda', 'Describe lenguas que tartamudean o hablan con dificultad, en Isaías 32:4 dentro de una profecía de restauración. El español «tartamudos» captura con precisión este sentido. El contexto promete que en el reino venidero «la lengua de los tartamudos hablará pronta y claramente», una reversión del juicio de Isaías 28 donde Dios hablaría al pueblo mediante extranjeros de labios balbucientes.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (124053, 'spa', 'subir, ascender (Qal)', 'Acepción dominante en Qal (779×): movimiento físico hacia arriba — ascender montañas, entrar en ciudades de mayor elevación, subir a la batalla o acercarse al santuario de Dios. Árabe صَعِدَ, coreano 올라가다, suajili kupanda confirman el vector espacial ascendente. Gn 13:1 (Abram subiendo de Egipto) y 1 R 18:42 (Elías ascendiendo al Carmelo) son instancias paradigmáticas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (124061, 'spa', 'ofrecer sacrificio (Hifil)', 'Uso causativo Hifil en contextos sacrificiales (41×): hacer que una ofrenda ascienda, es decir, ofrecer holocaustos sobre el altar. Gn 8:20 (la ofrenda de Noé tras el diluvio) y Gn 22:2, 13 (la ligadura de Isaac) son textos fundacionales. El sustantivo עֹלָה «holocausto» deriva de esta misma raíz.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (124065, 'spa', 'levantarse, brotar (Qal)', 'Acepción Qal aplicada a fenómenos naturales que se elevan (25×): el sol que sale, el alba que despunta, plantas que brotan, niebla que asciende o agua que mana. Árabe طَلَعَ «salir/aparecer» y suajili inuka/bubujika confirman la cualidad emergente y no volitiva. Gn 19:15 («al subir el alba»), Gn 32:26 y Gn 41:2 (vacas «subiendo» del Nilo) son textos clave.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (124125, 'spa', 'hacer subir, sacar (Hifil)', 'Uso causativo Hifil con personas como objeto (34×): hacer subir, sacar o conducir personas de un lugar a otro, preeminentemente cuando Dios hace subir a Israel de Egipto. Español «hice subir», francés «fit monter», alemán «heraufführen» captan el movimiento direccional causativo. Éx 3:8 y Gn 46:4 anclan esta acepción definitoria del éxodo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (124139, 'spa', 'ser alzado, retirarse (Nifal)', 'Nifal pasivo/reflexivo (7×): ser alzado, elevado o retirado, especialmente la nube de la presencia de Dios que se elevaba del tabernáculo como señal para partir. Éx 40:36–37 y Nm 9:17–22 se centran en los movimientos de la columna de nube que gobernaban la marcha de Israel por el desierto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (124194, 'spa', 'encender lámparas (Hifil)', 'Uso especializado del Hifil para disponer o encender las lámparas del candelabro del tabernáculo (6×). El hebreo conserva la metáfora direccional de hacer que la llama «suba». Éx 25:37, 30:8 y 40:4, 25 describen el deber sacerdotal de atender el candelabro, y Nm 8:2 lo ordena directamente a Aarón.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (124202, 'spa', 'rumiar (Hifil)', 'Uso técnico zoológico del Hifil (2×) en las leyes dietéticas: hacer subir el bolo alimenticio, es decir, rumiar. Lv 11:4 y Dt 14:7 emplean esta expresión para clasificar animales que rumian pero carecen de pezuña hendida (el camello, la liebre y el damán), declarándolos impuros.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (124267, 'spa', 'Holocaustos', 'Forma plural aramea para holocaustos en Esdras 6:9, dentro del decreto del rey Darío que proveía animales y suministros para el culto del templo. La evidencia multilingüe («para-ofrendas-quemadas») muestra una comprensión consistente de estos como sacrificios totalmente consumidos. Este documento administrativo del período persa demuestra cómo el culto distintivo de Israel fue reconocido por autoridades imperiales.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (124268, 'spa', 'Rama, fronda -- ramas frondosas de rboles, usadas en la forma de plural construc', 'Rama, fronda -- ramas frondosas de rboles, usadas en la forma de plural constructo especialmente en el contexto de recoger materiales para la Fiesta de los Tabernculos (Sucot). Las cinco ocurrencias en Nehemas 8:15 se refieren a ramas de olivo, mirto, palma y otros rboles tradas para construir cabanas temporales. El espaol ''ramas de'' refleja este desplazamiento de la hoja individual al ramaje frondoso como material de construccin festiva.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (124269, 'spa', 'Hoja, follaje -- la hoja o follaje de un rbol, usado tanto literalmente como en ', 'Hoja, follaje -- la hoja o follaje de un rbol, usado tanto literalmente como en rica aplicacin figurativa. Gnesis 3:7 registra el primer uso humano de hojas de higuera como cobertura, y Gnesis 8:11 presenta la hoja de olivo como seal del retroceso de las aguas del diluvio. El Salmo 1:3 y Jeremas 17:8 usan la hoja que no se marchita como smbolo de la vitalidad del justo, mientras Isaas 64:5 y Job 13:25 retratan la hoja arrastrada y marchita como imagen de fragilidad humana.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (124282, 'spa', 'holocausto (sacrificio)', 'Sacrificio animal completo consumido enteramente por el fuego sobre el altar, expresando adoración, expiación o consagración a Dios. Con 286 ocurrencias es el sentido abrumadoramente dominante, abarcando altares patriarcales (Gn 22:2-3, el casi-sacrificio de Isaac), legislación mosaica (Lv 1:3-17), ofrendas diarias y festivas (Nm 28-29) y dedicaciones reales (1 R 8:64).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (124317, 'spa', 'anomalía textual (Is 61:8)', 'Una sola ocurrencia anómala en Isaías 61:8 donde las traducciones multilingües divergen marcadamente: español ''con injusticia'', pero francés ''holocauste'' y alemán ''Brandopfer''. Esto refleja probablemente una ambigüedad textual o de análisis: el hebreo be''awlah (''con maldad'', de la raíz ''wl) es gráficamente cercano a be''olah (''con holocausto''). La mayoría de los especialistas actuales lo tratan como raíz distinta.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (124323, 'spa', 'Cargo legal', 'Tres apariciones en Daniel 6:4-5, todas en la expresión que busca «motivos de acusación» contra Daniel. La evidencia multilingüe muestra enfoques variados: algunas versiones traducen «ocasión» y otras ofrecen transliteración. El contexto legal es claro: los enemigos de Daniel necesitaban un cargo formal ante el rey, pero su administración intachable no les dio oportunidad alguna.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (124324, 'spa', 'Injusticia violenta', 'Injusticia o maldad violenta en Oseas 10:9, posiblemente una variante ortográfica. Las traducciones lo vierten como «iniquidad», captando la dimensión moral. Oseas lo usa para caracterizar la rebelión persistente de Israel, vinculándola con la atrocidad de Gabaa (Jueces 19-21). El término enfatiza cómo la injusticia social y la violencia son inseparables de la desobediencia espiritual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (124325, 'spa', 'Jefe edomita', 'Tres apariciones (Génesis y Crónicas con variante Ketiv/Qeré), todas referidas a un solo jefe edomita. La evidencia multilingüe refleja las variantes textuales: Alvá/Alías/Alva. Las listas genealógicas de Génesis 36 y 1 Crónicas 1 documentan la estructura tribal de Edom, cumpliendo la promesa de que Esaú también sería padre de naciones.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (124326, 'spa', 'Vigor de la juventud', 'Estado abstracto y energía de la juventud, siempre en plural constructo con sufijos posesivos, enfatizando la vitalidad y su carácter transitorio. En Job 20:11 el vigor juvenil satura los huesos del impío para luego perecer; en 33:25 describe una renovación física milagrosa. El Salmo 89:45 e Isaías 54:4 confirman que el campo semántico se centra en la plenitud vital.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (124328, 'spa', 'Sanguijuela voraz', 'La sanguijuela chupasangre de Proverbios 30:15, que introduce un dicho sobre cosas insaciables. El proverbio declara que «la sanguijuela tiene dos hijas: ¡Dame! ¡Dame!», usando sus dos ventosas como metáfora vívida de la codicia inextinguible. La imagen sirve como advertencia sapiencial contra el deseo desenfrenado que nunca encuentra satisfacción.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (124329, 'spa', 'Exultar, regocijarse jubilosamente -- exultar o regocijarse con triunfo jubiloso', 'Exultar, regocijarse jubilosamente -- exultar o regocijarse con triunfo jubiloso, expresando una alegra exuberante y a veces exttica. Aparece en la alabanza teofnica (Sal 60:6; 108:7, donde Dios mismo exulta), en convocatorias a la adoracin (Sof 3:14; Sal 68:4; 149:5), en testimonio personal de gozo (Sal 28:7; Hab 3:18), y negativamente sobre la jactancia de los malvados (Sal 94:3; Jer 51:39). La creacin csmica exulta en el Salmo 96:12.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (124344, 'spa', 'Jubiloso inconsciente', 'Quien exulta o celebra jubilosamente en Isaías 5:14, dentro del oráculo de juicio del profeta. Esta exultación ocurre en medio de ceguera espiritual y decadencia moral. Los que festejan y se regocijan, ignorando la obra y la justicia de Dios, verán su celebración truncada por el juicio divino, transformando su gozo en tragedia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (124345, 'spa', 'Tiniebla densa crepuscular', 'Oscuridad espesa o lobreguez, especialmente al anochecer. Génesis 15:17 la asocia con la tiniebla teofánica de la ceremonia del pacto de Dios. En Ezequiel 12, el uso reiterado (vv. 6, 7, 12) enfatiza la oscuridad bajo la cual ocurre el exilio simbólico, en paralelo con la huida nocturna de los refugiados. La oscuridad cumple funciones literales y simbólicas: encubre los movimientos y a la vez significa juicio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (124346, 'spa', 'Mano de mortero', 'El instrumento de molienda usado con el mortero en Proverbios 27:22, dentro de una metáfora sobre la persistencia de la necedad. La imagen proverbial enfatiza que la insensatez es fundamentalmente resistente a la corrección por la fuerza, una profunda observación sapiencial sobre los límites del castigo como medio de transformación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (124347, 'spa', 'Eli', 'Eli: nombre propio del sacerdote y juez en Silo que fue mentor del joven Samuel. Su narrativa abarca el voto de Ana (1 Sam 1:9-17), la llamada nocturna de Samuel (1 Sam 3:1-18), el oraculo contra su casa por tolerar la corrupcion de sus hijos (1 Sam 2:27-36) y su muerte al enterarse de la captura del arca (1 Sam 4:12-18). La destitucion de su linea sacerdotal se completa en 1 Reyes 2:27.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (124351, 'spa', 'Epíteto divino arameo que designa a Dios como gobernante supremo sobre todos los', 'Epíteto divino arameo que designa a Dios como gobernante supremo sobre todos los poderes terrenales y celestiales. Usado en las narrativas cortesanas de Daniel tanto de forma atributiva (''el Dios Altísimo'', Dan 3:26; 5:18, 21) como título independiente (''el Altísimo'', Dan 4:14, 21, 29, 31; 7:25). La alternancia ketiv-qere refleja la convención escribal aramea estándar. Este título es paralelo al hebreo Elyon y subraya el tema central del libro sobre la soberanía divina absoluta.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (124356, 'spa', 'Sentido arquitectónico principal de una habitación superior o cámara en la azote', 'Sentido arquitectónico principal de una habitación superior o cámara en la azotea —un espacio privado y elevado usado para alojamiento, devoción o retiro— que abarca 17 de 20 ocurrencias. La fresca cámara de verano de Eglón (Jue 3:20), la habitación de huésped que la sunamita construyó para Eliseo ''con paredes'' (2 Re 4:10) y la cámara sobre la puerta donde David lloró por Absalón (2 Sam 18:33) comparten este sentido.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (124362, 'spa', 'Extensión cosmológica notable donde los ''altos aposentos'' de Dios se convierten ', 'Extensión cosmológica notable donde los ''altos aposentos'' de Dios se convierten en el almacén celestial de los cielos. En el Salmo 104:3 Dios ''puso las vigas de sus altos aposentos sobre las aguas'', y desde esos aposentos riega los montes (Sal 104:13). Amós 9:6 sitúa de manera similar los ''pisos altos'' de Dios en los cielos. La misma palabra que designa una humilde habitación doméstica se eleva para describir la morada cósmica divina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (124367, 'spa', 'Sentido único que describe una subida o escalera en lugar de una habitación', 'Sentido único que describe una subida o escalera en lugar de una habitación. En 2 Crónicas 9:4 (paralelo a 1 Reyes 10:5), la reina de Sabá queda abrumada por la עֲלִיָּה de Salomón —su ''subida'' o escalera procesional por la que ascendía a la casa del SEÑOR. Esto lo distingue como un espacio de paso, no de habitación, señalando el camino ceremonial de ascenso.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (124369, 'spa', 'Superior o más alto en ubicación física, usado atributivamente para distinguir e', 'Superior o más alto en ubicación física, usado atributivamente para distinguir el más elevado de dos elementos: puertas, estanques, cámaras, cestas, manantiales o ciudades. La cesta de más arriba en Gn 40:17, Bet-horón de arriba en Jos 16:5 y la puerta superior en 2 R 15:35 dependen todos de este sentido espacial concreto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (124372, 'spa', 'Alto, exaltado o elevado en rango o estatus, usado predicativamente de naciones ', 'Alto, exaltado o elevado en rango o estatus, usado predicativamente de naciones o estructuras puestas por encima de otras. Dt 26:19 y 28:1 prometen que Dios pondrá a Israel por encima de todas las naciones. Este sentido traslada la verticalidad del primer significado al ámbito del honor y el prestigio, distinto del uso específicamente divino.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (124377, 'spa', 'El Altísimo, epíteto divino superlativo que designa a Dios como supremo sobre to', 'El Altísimo, epíteto divino superlativo que designa a Dios como supremo sobre todos los demás poderes y seres. Sal 97:9 declara al SEÑOR altísimo sobre toda la tierra, y Sal 89:27 lo aplica al rey davídico como reflejo de la soberanía divina. El francés ''Tres-Haut'' y el español ''Altísimo'' conservan el peso devocional y litúrgico de este título.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (124382, 'spa', 'Título divino que significa ''Altísimo'', afirmando la posición suprema de Dios po', 'Título divino que significa ''Altísimo'', afirmando la posición suprema de Dios por encima de todos los poderes cósmicos y terrenales. Atestiguado por primera vez en la bendición de Melquisedec como El Elyon, ''Dios Altísimo, creador del cielo y de la tierra'' (Gn 14:18-22). Deuteronomio 32:8 atribuye al Elyon el acto soberano de repartir las naciones. En los Salmos se combina libremente con YHWH (Sal 7:18), Elohim (Sal 57:3) y El (Sal 78:35). El Salmo 82:6 extiende el título a seres llamados ''hijos del Altísimo''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (124390, 'spa', 'Título divino supremo', 'Título divino arameo ''Altísimo'' (עֶלְיוֹן) que enfatiza la autoridad suprema de Dios. Las cuatro apariciones en Daniel 7 (vv. 18, 22, 25, 27) ocurren en contextos donde los ''santos del Altísimo'' reciben dominio eterno tras la derrota de los reinos terrenales. El título subraya la soberanía trascendente de Dios en la visión apocalíptica de la historia mundial que culmina en el gobierno divino.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (124391, 'spa', 'Exultante, jubiloso', 'Exultante o jubiloso, que describe un estado de regocijo ruidoso y triunfal. Se usa predominantemente en oráculos proféticos de juicio donde las ciudades son personificadas celebrando antes de su caída: Jerusalén como la ''ciudad jubilosa'' (Is 22:2), la antigua Tiro (Is 23:7) y Nínive (Sof 2:15). También describe personas en Is 13:3 y el silenciamiento de la algarabía en Is 24:8.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (124397, 'spa', 'Horno o crisol', 'Término que aparece en el Salmo 12:6 relacionado con la refinación de metales, probablemente un horno o crisol. A pesar de la incertidumbre textual, el contexto emplea claramente la imaginería metalúrgica para afirmar que las promesas de Dios son completamente fiables, purificadas siete veces como plata refinada, sin mezcla alguna de falsedad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (124398, 'spa', 'Hecho, acto u obra realizada por Dios o por los seres humanos, usado ampliamente', 'Hecho, acto u obra realizada por Dios o por los seres humanos, usado ampliamente para referirse a conductas tanto loables como reprochables. El salmista proclama los actos de Dios entre los pueblos (1 Cr 16:8 = Sal 105:1), y el Sal 66:5 invita a contemplar sus obras portentosas. Ezequiel emplea repetidamente el plural para las prácticas corruptas de Israel (Ez 20:43; 36:17, 19).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (124400, 'spa', 'Acusación formal, cargo inventado o pretexto levantado contra alguien en un cont', 'Acusación formal, cargo inventado o pretexto levantado contra alguien en un contexto legal. Aparece exclusivamente en Dt 22:14, 17, donde un marido presenta alilot devarim (''cargos infundados'') contra su esposa, alegando que no era virgen. La especificidad forense se confirma por las traducciones: ''pretextos'' en español y ''accusations'' en francés, que estrechan el sentido general de ''hechos'' hacia una fabricación deliberada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (124413, 'spa', 'Obra poderosa de Dios', 'La obra o acción poderosa de Dios en Jeremías 32:19, emparejada con su gran consejo. La evidencia multilingüe muestra poca variación (español: «de-obra»), reconociéndolo como referencia a la acción divina. El contexto de la compra simbólica de tierra por Jeremías enfatiza que las obras de Dios cumplirán sus promesas de restauración, aun cuando las circunstancias parezcan contradecir esas promesas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (124414, 'spa', 'Regocijo de opresores', 'El regocijo o exultación de los opresores en Habacuc 3:14, caracterizado por su deleite en devorar al pobre. Las traducciones (español: «su-regocijo», francés: «joie») lo identifican como celebración, pero el contexto deja claro que se trata de un gozo pervertido: hallar placer en victimizar a otros. Habacuc lo presenta como la actitud que el juicio venidero de Dios confrontará.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (124415, 'spa', 'Aposento alto de oración', 'La cámara superior o aposento alto de Daniel en Daniel 6:10, donde mantenía su práctica de oración diaria hacia Jerusalén. La evidencia multilingüe (español: «en-su-aposento-alto», francés: «hauteur») lo identifica consistentemente como una habitación elevada y privada. Este detalle arquitectónico es crucial para la narrativa: la fidelidad de Daniel era tanto privada como pública, visible a quienes buscaban acusarlo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (124416, 'spa', 'Obras y prácticas humanas', 'Las obras o prácticas que caracterizan la conducta humana en Zacarías 1:4, apareciendo en el llamado al arrepentimiento. Las traducciones multilingües muestran un sentido posesivo (español: «y-de-vuestras-obras»), indicando que el pueblo es dueño de sus acciones. El mensaje de Zacarías es que el retorno a Dios requiere no solo un cambio de actitud, sino una transformación concreta en las acciones cotidianas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (124417, 'spa', 'tratar con, actuar hacia', 'Piel: tratar con alguien, actuar hacia otro — un sentido más amplio y menos inherentemente negativo que el Hitpael. En Lamentaciones 1:22 y 2:20, Jerusalén clama a Dios por cómo la ha tratado y pregunta a quién le ha hecho así. La severidad proviene del contexto, no del verbo mismo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (124418, 'spa', 'burlarse, abusar, maltratar', 'Hitpael: burlarse, escarnecer, abusar, tratar con crueldad. Sentido dominante, usado para la burla de Dios contra Egipto (Éx 10:2), la frustración de Balaam con su burra (Nm 22:29), la atrocidad de Guibeá (Jue 19:25), el temor de los filisteos al escarnio (1 S 31:4) y el endurecimiento divino de Egipto (1 S 6:6).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (124420, 'spa', 'ocuparse en, practicar', 'Infinitivo Hitpael: ocuparse en algo, practicar o cometer acciones deliberadamente. El Salmo 141:4 ora para que el corazón no se incline ''a practicar obras impías''. Refleja la cualidad deliberada y autocomprometida de dedicarse a una actividad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (124422, 'spa', 'causar aflicción, afligir', 'Piel con objeto emocional: causar dolor, afligir o tratar de modo doloroso. Lamentaciones 3:51 dice ''mi ojo aflige mi alma'' — una aplicación especializada donde el ''tratar'' produce sufrimiento. La dimensión interior y psicológica lo distingue del ''tratar con'' interpersonal del sentido 2.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (124424, 'spa', 'ser tratado, padecer', 'Pual pasivo: ser tratado, recibir un trato severo. Lamentaciones 1:12 pide a los espectadores que contemplen el sufrimiento ''que me ha sido hecho''. Preserva el encuadre pasivo. Es la perspectiva del receptor del trato severo descrito activamente en los sentidos 1 y 2.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (124429, 'spa', 'Rebuscar, espigar', 'La acción de rebuscar uvas o aceitunas sobrantes tras la cosecha, usada literalmente en textos legales que protegen el derecho del pobre a espigar (Lv 19:10; Dt 24:21). Se extiende figuradamente a la persecución militar en Jueces 20:45 y al juicio profético en Jeremías 6:9, donde el rebusco se convierte en metáfora de eliminación exhaustiva.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (124430, 'spa', 'Conducta infantil del líder', 'El acto de comportarse infantil o inmaduramante en Isaías 3:12, referido al gobernante de Jerusalén. Las traducciones varían (español: «un-niño»), pero el contexto deja clara la crítica: el liderazgo carece de la madurez y sabiduría necesarias para guiar a la nación. Esto forma parte de la acusación mayor de Isaías contra el liderazgo fallido de Judá, donde la inmadurez de los gobernantes acarrea sufrimiento al pueblo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (124431, 'spa', 'Hundir en humillación', 'El acto de empujar o hundir hacia abajo en Job 16:15, usado figuradamente para describir a Job hundiendo su propio cuerno (símbolo de fuerza y orgullo) en el polvo. Las traducciones capturan esta imagen (español: «y-he-hundido»). La metáfora expresa la profunda humillación de Job: no solo experimenta la derrota sino que la reconoce activamente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (124432, 'spa', 'Sentido básico intransitivo (Peal)', 'Sentido básico intransitivo (Peal): entrar, ir adentro, presentarse ante un lugar o una presencia real. Daniel entra ante el rey (Dan 2:16), va al salón del banquete de la reina (Dan 5:10), y entra en su propia casa para orar (Dan 6:11). Los sabios y encantadores igualmente entran ante Nabucodonosor (Dan 4:7; 5:8).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (124434, 'spa', 'Sentido causativo (Haphel)', 'Sentido causativo (Haphel): hacer entrar a alguien, introducir, causar que entre. Arioc hace entrar a Daniel ante el rey (Dan 2:25), el rey ordena que los encantadores sean hechos entrar (Dan 4:6; 5:7), y Daniel mismo pide ser introducido (Dan 2:24). Preserva la estructura de doble agente: uno que causa y otro que entra.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (124437, 'spa', 'Sentido pasivo (Hophal)', 'Sentido pasivo (Hophal): ser traído o llevado ante otro agente, típicamente a una audiencia real. Daniel es traído ante Belsasar (Dan 5:13), los vasos del templo de Jerusalén son traídos (Dan 5:15), y la piedra es traída y colocada sobre el foso (Dan 6:18). Cada caso involucra una acción solemne y oficial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (124443, 'spa', 'Rebusco (de uvas)', 'El rebusco de uvas u olivas: racimos pequeños y sobrantes que permanecen después de la cosecha principal. Se emplea exclusivamente en contextos figurados para evocar un remanente lastimosamente reducido. En Jueces 8:2, Gedeón compara diplomáticamente su propio ''rebusco'' con la ''vendimia'' (בָּצִיר) de Efraín. Isaías utiliza la imagen dos veces: como vareo de olivas (17:6) y como secuela de la vendimia (24:13). Jeremías y Abdías lo aplican a la devastación dejada por invasores.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (124449, 'spa', 'El Nifal estativo', 'El Nifal estativo: estar en un estado de ocultamiento respecto a la vista o al conocimiento. Levítico 4:13 y 5:2-4 emplean repetidamente esta forma para la impureza ritual que escapa a la conciencia del individuo: el pecado es real pero oculto para el propio pecador. En Job 28:21, la sabiduría misma está ''escondida de los ojos de todo viviente''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (124450, 'spa', 'El Hitpael reflexivo', 'El Hitpael reflexivo: esconderse a sí mismo o apartar deliberadamente la mirada. Deuteronomio 22:1-4 usa esta forma tres veces para quien ve al animal extraviado de su prójimo y finge no darse cuenta, una acusación ética punzante. En el Salmo 55:1, el salmista suplica a Dios que no ''se esconda'' de su clamor.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (124451, 'spa', 'El Hifil causativo', 'El Hifil causativo: esconder algo o a alguien de forma activa y deliberada. Dios esconde su rostro (Is 1:15), y los humanos ocultan transgresiones o apartan la vista de su deber (1 S 12:3). El español ''esconde'' capta la agencia volitiva: no se trata de una oscuridad accidental, sino de una supresión intencional de lo que debería ser visible o conocido.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (124455, 'spa', 'Participios empleados como sustantivos que denotan cosas ocultas o asuntos secre', 'Participios empleados como sustantivos que denotan cosas ocultas o asuntos secretos. En el Salmo 90:8, ''nuestros pecados secretos'' (participio pasivo Qal) quedan expuestos ante la luz de Dios. Eclesiastés 12:14 declara que Dios traerá a juicio toda ''cosa oculta''. El Salmo 26:4 identifica a ''los que se esconden'', aquellos que actúan con engaño encubierto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (124472, 'spa', 'Eternidad o perpetuidad —duración ilimitada que se extiende hacia el futuro', 'Eternidad o perpetuidad —duración ilimitada que se extiende hacia el futuro. Este es el sentido predominante, apareciendo en aclamaciones reales (''¡Oh rey, vive para siempre!'', Daniel 2:4; 6:7), en descripciones del reino eterno de Dios (Daniel 3:33; 7:14, 27) y en la doxología de Daniel 2:20. Las traducciones multilingües convergen notablemente: español ''eternidad'', árabe إلى الأبد, suajili ''milele''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (124474, 'spa', 'Tiempo antiguo o antigüedad —el mismo concepto temporal ilimitado dirigido retro', 'Tiempo antiguo o antigüedad —el mismo concepto temporal ilimitado dirigido retrospectivamente hacia el pasado distante. En Esdras 4:15 y 4:19, la frase מִן־יוֹמָת עָלְמָא significa ''desde los días antiguos'', en el contexto de la carta de los adversarios samaritanos advirtiendo a Artajerjes que Jerusalén ha sido rebelde ''desde tiempos antiguos''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (124479, 'spa', 'Doncella, mujer joven', 'Mujer joven en edad de casarse, generalmente soltera y presumida casta. El término aparece en momentos narrativos clave: Rebeca acercándose al pozo (Gn 24:43), la joven Miriam cuidando a Moisés (Éx 2:8), y de manera más trascendente en la profecía del Emmanuel de Isaías (Is 7:14), donde la traducción de la LXX como parthenos configuró la teología cristiana. En español se traduce comúnmente como ''doncella''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (124485, 'spa', 'Ciudad levítica', 'Población levítica en Benjamín mencionada en Josué 21:18. Las traducciones principales la conservan como «Almón», reconociéndola como idéntica a Alemet de 1 Crónicas 6:60. La asignación de ciudades a los levitas, quienes no recibieron territorio tribal propio, cumplía el propósito de extender el liderazgo religioso por todo Israel, asegurando que la enseñanza y el servicio sacerdotal fueran accesibles a todas las tribus.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (124487, 'spa', 'Pueblo de Elam', 'Los habitantes de Elam mencionados en Esdras 4:9 entre los pueblos reasentados en Samaria que se oponían a la reconstrucción del templo de Jerusalén. Las traducciones los identifican consistentemente como «elamitas» o «los elamitas», reconociéndolos como grupo étnico diferenciado. Su inclusión en esta lista demuestra cómo las políticas de deportación asirias y babilónicas crearon comunidades multiétnicas complejas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (124489, 'spa', 'Nombre propio bíblico', 'Nombre personal y topónimo que aparece en las genealogías benjaminitas (1 Cr 8:36; 9:42) y como ciudad levítica (1 Cr 6:60). El nombre presenta variantes ortográficas (Alemet/Alamet) y puede ser idéntico a Almón mencionado en otros pasajes. Las diversas transliteraciones de la LXX indican fluidez textual en la transmisión de nombres propios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (124490, 'spa', 'Regocijo y deleite', 'Tres apariciones que muestran formas verbales en Qal, Nifal e Hitpael. Job 20:18 niega al impío el verdadero regocijo por sus ganancias. La imagen de Job 39:13 de alas aleteando gozosamente captura una exultación natural y espontánea. El uso de Proverbios 7:18 en el discurso de seducción demuestra la neutralidad semántica del término: puede describir gozo legítimo o ilegítimo según el contexto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (124491, 'spa', 'Sorber ávidamente', 'Verbo de significado incierto en Job 39:30, que probablemente describe a las crías del águila bebiendo sangre, aunque posiblemente sea un error textual por otro verbo. Las traducciones reflejan la incertidumbre (español: «sorben»), pero todas transmiten la imagen de consumir sangre. El contexto más amplio de las descripciones animales en Job 39 enfatiza la naturaleza feroz e indómita de las criaturas como parte de la respuesta de Dios a Job.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (124492, 'spa', 'Costillas de presa', 'Las costillas en la boca de la bestia con forma de oso en Daniel 7:5. Todas las traducciones principales lo vierten consistentemente como «costillas» (español: «costillas», francés: «côtes»), reconociendo la referencia anatómica. Las tres costillas simbolizan naciones o territorios devorados por el imperio que el oso representa, comúnmente interpretado como Medo-Persia. La imagen visual de un depredador con huesos de sus víctimas en la boca comunica conquista brutal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (124493, 'spa', 'Cubrir, revestir', 'Cubrir, incrustar o revestir una superficie, como en Cantares 5:14 donde el cuerpo del amado se describe como marfil ''cubierto de'' zafiros. La forma pasiva Pual enfatiza el estado resultante de estar revestido. El cognado árabe ghalafa (''enfundar'') y el asirio elpitu confirman un sentido base de cubrimiento físico que se extiende al desvanecimiento y al acto de velarse.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (124494, 'spa', 'Desmayarse o cubrirse', 'Estado de quedar cubierto, desmayado o envuelto en Ezequiel 31:15, describiendo la reacción de los árboles ante la caída del gran cedro. Las traducciones muestran un abanico interpretativo que converge en la imagen de ser abrumado o cubierto. El contexto alegórico de Ezequiel 31 emplea los árboles del Edén para representar naciones que reaccionan ante el juicio divino.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (124495, 'spa', 'Exultar, regocijarse', 'Exultar o regocijarse con una alegría intensa y frecuentemente triunfal, dirigida típicamente a Dios en adoración o acción de gracias. El verbo transmite un gozo que se desborda en expresión visible o vocal, paralelizado con cantar (zamar) y dar voces de júbilo (ranan). El cántico de Ana establece el patrón: ''mi corazón se regocija en el SEÑOR'' (1 S 2:1). Los Salmos lo emplean para la adoración comunitaria (Sal 5:11).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (124503, 'spa', 'El pueblo', 'El pueblo en Jeremías 17:19, donde aparece en la designación de una puerta pública. Las traducciones multilingües lo presentan con el artículo definido, indicando un lugar específico donde se congregaba la población. La instrucción a Jeremías de pararse en esta puerta subraya la proclamación pública: el profeta debía entregar la palabra de Dios donde el pueblo se reunía.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (124504, 'spa', 'pueblo, nación', 'Acepción dominante y casi exclusiva: cuerpo colectivo de personas, ya sea Israel como pueblo de la alianza de Dios, una nación extranjera o las naciones en general. Abarca usos en singular y plural, con o sin artículo, preposiciones y sufijos posesivos. Las glosas en todas las lenguas convergen en sustantivos colectivos — «el pueblo», «le peuple», «das Volk» — confirmando un único significado nuclear.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (124576, 'spa', 'uso ambiguo', 'Ocurrencia en 2 S 13:34 donde la acepción es contextualmente incierta o debatida. El pasaje describe al vigía viendo gente que viene, y la palabra puede funcionar en su sentido colectivo habitual pero con un referente ambiguo. La evidencia de las glosas es idéntica a la acepción 1, lo que sugiere una instancia marginal o textualmente difícil más que una acepción semántica distinta.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (124581, 'spa', 'mi pueblo (Cnt 6:12)', 'Ocurrencia en Cnt 6:12, donde עַמִּי aparece en un versículo notoriamente difícil: «No supe; mi deseo me puso entre los carros de mi pueblo noble» (o «de Aminadab»). El posesivo «mi pueblo» es claro por las glosas, pero si עַמִּי־נָדִיב es un nombre propio compuesto o «mi pueblo noble» sigue siendo uno de los problemas textuales más debatidos del Cantar.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (124586, 'spa', 'Parentela, pueblo propio', 'Parentela, pueblo propio: parentela o clan ancestral, mas frecuentemente en plural con sufijos pronominales en formulas de muerte y exclusion del pacto. La expresion nikhrat me-ammeyha (''cortado de sus pueblos'', Gn 17:14) y ne''esaf el-ammav (''reunido con sus pueblos'', Gn 25:8) tratan al grupo de parientes difuntos como una realidad continuada a la que uno se une o de la que es separado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (124590, 'spa', 'Pueblo, nacion (colectivo)', 'Pueblo, nacion (colectivo): designacion colectiva del pueblo nacional propio, usada en singular con sufijos en el discurso profetico o legal. En Gn 49:29 Jacob ordena ser sepultado con ammai (''mis parientes''), y en Jue 14:3 los padres de Sanson protestan porque no hay mujer adecuada entre ammi (''mi pueblo''). El paso del plural parentela al singular nacion refleja como el termino puede abarcar tanto el vinculo familiar intimo como la identidad nacional mas amplia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (124600, 'spa', 'pueblo, nación', 'Sustantivo colectivo para un pueblo o nación, equivalente arameo del hebreo עַם. Se usa en las porciones arameas imperiales de Daniel y Esdras para designar grupos nacionales o étnicos, especialmente en fórmulas regias (''todos los pueblos, naciones y lenguas'', Dn 3:4; 7:14) y en decretos administrativos referentes al pueblo judío (Esd 5:12; 7:13, 25).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (124606, 'spa', 'compañía, junto con', 'Acepción comitativa predominante: acompañamiento, asociación, estar junto con alguien o algo. Abarca 956 de 978 ocurrencias y es el significado por defecto en todas las formas con sufijo y construcciones. Abraham intercede ante Dios respecto a Sodoma: «¿Destruirás al justo con el impío?» (Gn 18:23). La evidencia multilingüe es unánime: español con, francés avec, alemán mit.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (124616, 'spa', 'adversativo, contra', 'Acepción adversativa: contra, en oposición a. Seis ocurrencias invierten el significado comitativo esperado para expresar hostilidad o rebeldía. Moisés acusa dos veces a Israel: «Habéis sido rebeldes contra el Señor» (Dt 9:7, 24), y el salmista pregunta «¿Quién se levantará por mí contra los malhechores?» (Sal 94:16).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (124617, 'spa', 'proximidad espacial', 'Proximidad espacial: junto a, cerca de, en un lugar determinado. Quince ocurrencias desplazan el peso semántico del acompañamiento relacional a la cercanía física. Isaac mora «junto a» Beer-lajai-roí (Gn 25:11), Jacob entierra los dioses extranjeros «bajo la encina que estaba junto a Siquem» (Gn 35:4) y Hai se describe «junto a» Bet-avén (Jos 7:2).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (124624, 'spa', 'posesión, en poder de', 'Acepción posesiva o existencial: en poder de, a disposición de. Una sola ocurrencia clara en Gn 24:25, donde Rebeca declara «hay paja y forraje en abundancia con nosotros», es decir, «los tenemos disponibles». Francés chez nous y árabe عِنْدَنَا captan perfectamente el matiz posesivo. Esta acepción marginal ilustra cómo el sentido de proximidad espacial puede derivar hacia la posesión.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (124627, 'spa', 'Origen desde la proximidad', 'Origen desde la proximidad: ''de junto a'', ''de la presencia de'', indicando partida, procedencia o derivación desde la compañía de alguien. Este sentido abrumadoramente dominante (70 ocurrencias) rige verbos de salir, tomar, retirar y solicitar — Lot separándose de Abraham (Gn 13:14), el espíritu de Yahvé apartándose de Saúl (1 S 16:14), Eliseo pidiendo una doble porción antes de que Elías sea llevado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (124633, 'spa', 'Fuerza comparativa en una construcción rara', 'Fuerza comparativa en una construcción rara: ''más que lo que está con'' alguien, expresando superioridad sobre los recursos o la alianza de otro. Solo una ocurrencia clara — el discurso de Ezequías animando a Jerusalén durante el asedio asirio: ''con nosotros hay más que con él'' (2 Cr 32:7), donde מֵעִמּוֹ contrasta al aliado divino de Judá con el ejército meramente humano de Senaquerib.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (124643, 'spa', 'Preposición aramea de acompañamiento (''con, junto con''), que expresa asociación,', 'Preposición aramea de acompañamiento (''con, junto con''), que expresa asociación, proximidad, interacción cooperativa u hostil, y simultaneidad temporal. Aparece a lo largo de Daniel y Esdras con diversos sufijos pronominales (immi ''conmigo'', immeh ''con él'', immakh ''contigo'', immehon ''con ellos''). Pasajes clave incluyen la visión mesiánica de uno que viene con las nubes (Dn 7:13), el conocimiento divino (Dn 2:22) y la guerra contra los santos (Dn 7:21).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (124649, 'spa', 'estar de pie, pararse', 'Postura física de estar de pie o ponerse en pie: el sentido básico e indiferenciado del Qal, que abarca aproximadamente el 59% de las ocurrencias. Abraham estaba de pie junto a los ángeles bajo el árbol (Gn 18:8) y Faraón se puso junto al Nilo en su sueño (Gn 41:1). Es el uso concreto y posicional más elemental del verbo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (124655, 'spa', 'apostar, designar', 'Hifil causativo: apostar, designar o colocar a una persona en un puesto o lugar. José presentó a su padre ante Faraón (Gn 47:7) y Moisés dispuso a los levitas (Nm 8:13). La agencia causativa distingue claramente este sentido del estar de pie intransitivo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (124656, 'spa', 'servir, asistir', 'Estar de pie ante un superior en servicio o atención: sentido especializado donde la posición implica función litúrgica o cortesana. Los levitas que ''estaban de pie para ministrar'' (1 Cr 6:33), los servidores de Salomón que ''estaban ante él'' (2 Cr 9:7) y quienes servían ante Dios en función sacerdotal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (124658, 'spa', 'mantenerse firme, soportar', 'Mantenerse firme, soportar o resistir: extensión metafórica donde la postura física se vuelve figura de perseverancia ante la oposición o el paso del tiempo. ''¿Quién puede estar de pie ante el Señor?'' (1 S 6:20) y ''nadie podrá resistir ante ti'' (Jos 10:8) ejemplifican la transición de postura a constancia moral.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (124670, 'spa', 'erigir, establecer', 'Hifil: erigir, levantar o establecer un objeto, institución o decreto. El sacerdote presentará a la persona ante el Señor (Lv 14:11) y las ofrendas se colocan ante el tabernáculo (Lv 16:7). El cognado arameo ''pilar'' (ammuda) conserva este sentido causativo concreto de poner algo en posición vertical.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (124674, 'spa', 'detenerse, parar', 'Detenerse, parar, cesar el movimiento o la actividad: el aspecto de cesación del estar de pie. A Lot se le dijo que no se detuviera al huir de Sodoma (Gn 19:17), y Lea dejó de dar a luz (Gn 29:35, lit. ''se detuvo de dar a luz''). Este sentido de interrupción se diferencia de la postura estática.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (124759, 'spa', 'ser puesto de pie (pasivo)', 'Hofal pasivo: ser hecho estar de pie, ser colocado en posición por la agencia de otro. Solo dos ocurrencias: el macho cabrío expiatorio ''será presentado vivo'' ante el Señor (Lv 16:10) y el rey ''fue sostenido en pie'' en su carro (1 R 22:35). Transmite causación pasiva.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (124875, 'spa', 'Hacer tambalear', 'La acción de hacer temblar o tambalear algo en Ezequiel 29:7, usado figuradamente para describir cómo Egipto desestabilizó las espaldas de Israel. Las traducciones captan el sentido causativo del verbo. La metáfora del bastón de caña que hiere en vez de sostener expresa la acusación de Ezequiel contra Egipto como aliado traicionero.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (124876, 'spa', 'Puesto, lugar asignado', 'Un lugar donde estar de pie o puesto asignado: el sitio fijo donde alguien se posiciona para el culto, la asamblea litúrgica o un encuentro divino. El término aparece típicamente en la frase עַל־עָמְדָם (''en su lugar''), describiendo las posiciones organizadas de levitas y adoradores durante las reformas del templo bajo Ezequías (2 Cr 30:16), Josías (2 Cr 34:31; 35:10) y Nehemías (Neh 8:7; 9:3; 13:11). En Daniel designa el lugar donde el profeta se encontraba durante sus visiones.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (124879, 'spa', 'Conmigo', 'Conmigo: expresa acompanamiento, presencia, companerismo o asociacion entre el hablante y otra parte. Este sentido abrumadoramente dominante abarca la presencia divina (''el Senor estaba conmigo''), la compania humana (''ve conmigo''), la solidaridad del pacto (''trata bondadosamente conmigo'') e incluso el encuentro adversarial (''contiende conmigo''). Dios promete ''Yo estoy contigo'' (Gn 21:22; 26:3, 28).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (124882, 'spa', 'De conmigo', 'De conmigo: la preposicion combinada con מִן (min, ''de'') para indicar separacion o partida de la presencia del hablante. Saul dice a Samuel que las asnas han sido halladas y su padre ha pasado de preocuparse por ellas a preocuparse por ''nosotros'' (1 Sam 10:2), y Jonatan pide licencia a David para ausentarse (1 Sam 20:28). La construccion compuesta preserva la nocion de alejamiento desde la compania del hablante.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (124885, 'spa', 'Conmigo mismo', 'Conmigo mismo: matiz reflexivo donde el propio hablante es a la vez sujeto y companero, usado en el deseo de Job de poder defender su caso sin temor: ''porque no soy asi conmigo mismo'' (Job 9:35). La cualidad autorreferencial distingue este uso del acompanamiento ordinario, pues Job contempla su propio estado interior ante el tribunal divino.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (124888, 'spa', 'Posición firme', 'Un lugar donde estar de pie o una posición en Miqueas 1:11, aunque el texto se reconoce como difícil. Las traducciones muestran incertidumbre pero convergen en la idea de un sitio donde pararse. El contexto de juicio sugiere la eliminación de seguridad y estabilidad: quienes se creían firmemente establecidos perderán su base de apoyo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (124889, 'spa', 'Correspondiente a, paralelo a', 'Correspondiente a, paralelo a: correspondencia espacial o paralelismo, el sentido central con 15 ocurrencias, que describe algo posicionado directamente en paralelo, correspondiente o equivalente a otra cosa. Especialmente prominente en las visiones del templo y la division de la tierra de Ezequiel (Ez 45:6-7; 48:13, 18, 21) y en las listas organizativas de Cronicas donde una division ''corresponde a'' otra (1 Cr 24:31; 25:8; 26:12).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (124891, 'spa', 'Junto a, adyacente a', 'Junto a, adyacente a: proximidad fisica y cercania, mas que correspondencia abstracta. Este es el sentido de la construccion del tabernaculo: los anillos se colocan ''junto a'' el borde del marco (Ex 25:27; 37:14), las hombreras se situan ''al lado de'' el efod (Ex 28:27; 39:20), y la grasa se retira ''junto a la espina dorsal'' (Lv 3:9).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (124893, 'spa', 'Enfrente, en oposicion', 'Enfrente, en oposicion: sentido marcadamente distinto que aparece solo dos veces, ambas en Ez 3:8, donde Dios endurece el rostro de Ezequiel ''contra'' los rostros de los rebeldes y su frente ''contra'' sus frentes. La duplicacion dentro de un mismo versiculo enfatiza que no se trata de mera proximidad espacial sino de confrontacion activa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (124897, 'spa', 'Desde junto a (con min)', 'Desde junto a (con min): una sola ocurrencia en 1 R 7:20 donde se antepone la preposicion min, creando me''ummat para indicar direccion de origen desde junto a la protuberancia en forma de vientre de las columnas. Es una extension espacial estandar: el mismo significado de ''junto a'' con la direccionalidad de ''desde'' anadida.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (124899, 'spa', 'De igual manera, lo mismo que', 'De igual manera, lo mismo que: una sola ocurrencia en Ec 5:16 donde la metafora espacial de ''junto a'' se ha abstraido en comparacion cualitativa: ''tal como vino, asi se ira.'' El pasaje del Qohelet usa ummat sin le-, significando ''conforme a, de la misma manera'' en modo mas que en posicion.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (124901, 'spa', 'Ciudad de Aser', 'Un asentamiento mencionado en Josué 19:30 como parte de la herencia de Aser. El nombre aparece con la conjunción «y» en el texto hebreo, indicando su posición dentro de una lista de límites territoriales. Las traducciones preservan la forma fonética «Uma» de manera consistente entre los idiomas, reflejando su carácter de identificador geográfico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (124902, 'spa', 'columna arquitectónica', 'Pilar o columna arquitectónica que sostiene un edificio, el tabernáculo o el templo. Abarca las columnas de madera de acacia del tabernáculo (Éx 26:32, 37), los pilares de cedro del palacio de Salomón (1 R 7:2) y las columnas que Sansón derribó (Jue 16:25-29). También se usa figuradamente para las ''columnas del cielo'' y las ''columnas de la tierra'' (Job 9:6; 26:11).');